#!/usr/bin/env python3
"""
Check what the JSON Schema specifications actually require.
"""

import jsonschema
import json


def test_valid_json_schema_formats():
    """Test various valid JSON Schema formats."""

    # Schema with root as actual object and $defs
    valid_schema1 = {
        "type": "object",
        "properties": {
            "name": {"type": "string"}
        },
        "required": ["name"],
        "$defs": {
            "Person": {
                "type": "object", 
                "properties": {
                    "name": {"type": "string"}
                },
                "required": ["name"]
            }
        }
    }

    # Schema with root as reference to $defs (questionable)
    questionable_schema = {
        "$ref": "#/$defs/Person",
        "$defs": {
            "Person": {
                "type": "object",
                "properties": {
                    "name": {"type": "string"}
                },
                "required": ["name"]
            }
        }
    }

    # Schema with root reference to incorrect path
    invalid_schema = {
        "$ref": "#/defs/Person",  # Wrong: should be #/$defs/Person
        "$defs": {
            "Person": {
                "type": "object",
                "properties": {
                    "name": {"type": "string"}
                },
                "required": ["name"]
            }
        }
    }

    test_data = {"name": "John"}

    print("Testing valid schema (root is object):")
    try:
        validator = jsonschema.Draft202012Validator(valid_schema1)
        validator.validate(test_data)
        print("✅ Valid schema works")
    except Exception as e:
        print(f"❌ Valid schema failed: {e}")

    print("\nTesting questionable schema (root is reference to $defs):")
    try:
        validator = jsonschema.Draft202012Validator(questionable_schema)
        validator.validate(test_data)
        print("✅ Questionable schema works")
    except Exception as e:
        print(f"❌ Questionable schema failed: {e}")

    print("\nTesting invalid schema (root reference wrong path):")
    try:
        validator = jsonschema.Draft202012Validator(invalid_schema)
        validator.validate(test_data)
        print("✅ Invalid schema works (unexpected)")
    except Exception as e:
        print(f"❌ Invalid schema failed: {e}")


if __name__ == "__main__":
    test_valid_json_schema_formats()

