#!/usr/bin/env python3
"""
Comprehensive test of the fix for all_refs=True validation issue.
"""

import json
import jsonschema
from dataclasses import dataclass
from typing import List, Optional
from mashumaro.jsonschema import build_json_schema
from mashumaro.jsonschema.builder import JSONSchemaBuilder
from mashumaro.jsonschema.dialects import DRAFT_2020_12, OPEN_API_3_1


@dataclass
class InnerClass:
    value: int
    name: str


@dataclass  
class MiddleClass:
    inner: InnerClass
    count: int


@dataclass
class RootClass:
    """Complex nested structure to test all scenarios."""
    name: str
    middle: MiddleClass
    items: List[InnerClass]
    optional_item: Optional[InnerClass] = None


def test_main_issue_fixed():
    """Test that the main reported issue is fixed."""
    print("=== Testing Main Issue Fix ===")

    # Generate schema with all_refs=True (this was failing before)
    schema = build_json_schema(RootClass, all_refs=True)
    schema_dict = schema.to_dict()

    print("Generated schema keys:", list(schema_dict.keys()))

    # Should NOT be a root reference
    assert '$ref' not in schema_dict or len(schema_dict) > 1, "Root should not be just a reference"

    # Should have definitions
    assert '$defs' in schema_dict, "Should have definitions"

    # Should be validatable
    test_data = {
        "name": "test",
        "middle": {
            "inner": {"value": 42, "name": "inner"},
            "count": 5
        },
        "items": [
            {"value": 1, "name": "item1"},
            {"value": 2, "name": "item2"}
        ],
        "optional_item": {"value": 99, "name": "optional"}
    }

    try:
        validator = jsonschema.Draft202012Validator(schema_dict)
        validator.validate(test_data)
        print("✅ Complex schema validation succeeded!")
    except Exception as e:
        print(f"❌ Complex schema validation failed: {e}")
        return False

    return True


def test_nested_references_work():
    """Test that nested objects still become references."""
    print("\n=== Testing Nested References ===")

    schema = build_json_schema(RootClass, all_refs=True)
    schema_dict = schema.to_dict()

    # Check that nested objects use references
    middle_items = schema_dict['properties']['middle']['items']
    if '$ref' in middle_items:
        print(f"✅ Middle items use reference: {middle_items['$ref']}")
    else:
        print("⚠️  Middle items don't use reference")

    items_array_items = schema_dict['properties']['items']['items']
    if '$ref' in items_array_items:
        print(f"✅ Items array items use reference: {items_array_items['$ref']}")
    else:
        print("⚠️  Items array items don't use reference")

    return True


def test_jsonschema_builder_still_works():
    """Test that JSONSchemaBuilder behavior is preserved."""
    print("\n=== Testing JSONSchemaBuilder Compatibility ===")

    builder = JSONSchemaBuilder(dialect=DRAFT_2020_12, all_refs=True)
    schema = builder.build(RootClass)
    schema_dict = schema.to_dict()

    # Builder should still return references (that's its job)
    if '$ref' in schema_dict:
        print(f"✅ Builder returns reference: {schema_dict['$ref']}")
        # References should use correct format
        if schema_dict['$ref'].startswith('#/$defs/'):
            print("✅ Reference uses correct $defs format")
        else:
            print(f"⚠️  Reference format might be incorrect: {schema_dict['$ref']}")
        return True
    else:
        print("❌ Builder should return reference but doesn't")
        return False


def test_openapi_dialect():
    """Test OpenAPI dialect still works."""
    print("\n=== Testing OpenAPI Dialect ===")

    builder = JSONSchemaBuilder(dialect=OPEN_API_3_1)
    schema = builder.build(RootClass)
    schema_dict = schema.to_dict()

    if '$ref' in schema_dict:
        print(f"✅ OpenAPI builder returns reference: {schema_dict['$ref']}")
        # Should use OpenAPI format
        if schema_dict['$ref'].startswith('#/components/schemas/'):
            print("✅ OpenAPI reference uses correct format")
        else:
            print(f"⚠️  OpenAPI reference format: {schema_dict['$ref']}")
        return True
    else:
        print("❌ OpenAPI builder should return reference")
        return False


def test_without_all_refs():
    """Test that normal behavior is unchanged."""
    print("\n=== Testing Normal Behavior (all_refs=False) ===")

    schema = build_json_schema(RootClass, all_refs=False)
    schema_dict = schema.to_dict()

    # Should be a normal object schema
    assert 'type' in schema_dict and schema_dict['type'] == 'object'
    assert 'properties' in schema_dict

    # Should NOT have root reference
    assert '$ref' not in schema_dict

    # Should be validatable
    test_data = {
        "name": "test",
        "middle": {
            "inner": {"value": 42, "name": "inner"},
            "count": 5
        },
        "items": [
            {"value": 1, "name": "item1"},
            {"value": 2, "name": "item2"}
        ]
    }

    try:
        validator = jsonschema.Draft202012Validator(schema_dict)
        validator.validate(test_data)
        print("✅ Normal schema validation succeeded!")
        return True
    except Exception as e:
        print(f"❌ Normal schema validation failed: {e}")
        return False


def main():
    """Run all tests."""
    print("Running comprehensive tests for all_refs=True fix...\n")

    tests = [
        test_main_issue_fixed,
        test_nested_references_work,
        test_jsonschema_builder_still_works,
        test_openapi_dialect,
        test_without_all_refs,
    ]

    passed = 0
    total = len(tests)

    for test in tests:
        try:
            if test():
                passed += 1
        except Exception as e:
            print(f"❌ Test {test.__name__} failed with exception: {e}")

    print(f"\n=== Results: {passed}/{total} tests passed ===")

    if passed == total:
        print("🎉 All tests passed! The fix works correctly.")
    else:
        print("⚠️  Some tests failed. Review the implementation.")


if __name__ == "__main__":
    main()
